"use client";
import { FormEvent, useEffect, useState } from "react";
import Link from "next/link";
import { ArrowLeft, ArrowRight, Check } from "lucide-react";
import { clubs as demoClubs, type Club } from "@/lib/types";
import { createSupabaseBrowserClient } from "@/lib/supabase-browser";
import { SCHOOL_YEAR } from "@/lib/school";

export default function RequestChangePage() {
  const [availableClubs, setAvailableClubs] = useState<Club[]>(demoClubs);
  const [submitted, setSubmitted] = useState(false);
  const [busy, setBusy] = useState(false);
  useEffect(() => { const supabase = createSupabaseBrowserClient(); if (supabase) supabase.from("clubs").select("*").order("name").then(({ data }) => { if (data?.length) setAvailableClubs(data.map((club, index) => ({ ...club, color: demoClubs[index % demoClubs.length].color, icon: demoClubs[index % demoClubs.length].icon, members: 0 }))); }); }, []);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setBusy(true); const form = new FormData(event.currentTarget); const supabase = createSupabaseBrowserClient();
    if (supabase) await supabase.from("club_change_requests").insert({ student_name: form.get("name"), class_year: form.get("class_year"), contact: form.get("contact") || null, current_club_id: form.get("current_club"), requested_club_id: form.get("requested_club"), reason: form.get("reason"), school_year: SCHOOL_YEAR });
    else await new Promise((resolve) => window.setTimeout(resolve, 550));
    setBusy(false); setSubmitted(true);
  }
  if (submitted) return <main className="min-h-[calc(100vh-76px)] bg-[#f0f6fb] px-5 py-20 sm:px-8"><div className="mx-auto max-w-xl rounded-[28px] bg-white p-8 text-center shadow-soft sm:p-14"><div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-[#e7f4e9] text-shamrock"><Check size={30} /></div><p className="mt-7 text-[11px] font-bold uppercase tracking-[.2em] text-shamrock">Request received</p><h1 className="mt-3 text-4xl font-bold tracking-tight text-blue-950">We&apos;ll review it soon.</h1><p className="serif mt-5 text-sm leading-7 text-slate-500">A club leader or the Clubs Prefect will review your request and let you know what happens next.</p><Link href="/" className="mt-8 inline-block text-sm font-bold text-blue-900 underline underline-offset-8">Back to all clubs</Link></div></main>;
  return <main className="min-h-[calc(100vh-76px)] bg-[#f0f6fb] px-5 py-12 sm:px-8 sm:py-20"><div className="mx-auto grid max-w-5xl gap-12 lg:grid-cols-[.75fr_1.25fr] lg:gap-24"><div><Link href="/join" className="inline-flex items-center gap-2 text-xs font-bold text-blue-900"><ArrowLeft size={14} /> Back to registration</Link><p className="mt-12 text-[11px] font-bold uppercase tracking-[.2em] text-violet">Change request</p><h1 className="mt-3 text-4xl font-bold tracking-tight text-blue-950 sm:text-5xl">Need a<br /><span className="text-violet">different club?</span></h1><p className="serif mt-6 max-w-sm text-sm leading-7 text-slate-500">Tell us what you&apos;d like to change. Requests are reviewed by a club leader or the Clubs Prefect.</p><div className="mt-10 rounded-2xl bg-white p-4 text-xs leading-5 text-slate-500 shadow-card"><b className="text-blue-950">School year {SCHOOL_YEAR}</b><br />You can have up to two clubs at a time.</div></div><form onSubmit={submit} className="rounded-[26px] bg-white p-6 shadow-soft sm:p-9"><div className="grid gap-5 sm:grid-cols-2"><label className="text-xs font-bold text-blue-950 sm:col-span-2">Your full name<input required name="name" placeholder="e.g. Amina Wambui" className="outline-ring mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm font-normal text-slate-700 placeholder:text-slate-400 focus:border-blue-900 focus:bg-white" /></label><label className="text-xs font-bold text-blue-950">Class / year<select required name="class_year" defaultValue="" className="outline-ring mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm font-normal text-slate-700 focus:border-blue-900 focus:bg-white"><option value="" disabled>Select your class</option>{[7, 8, 9, 10, 11, 12, 13].map((year) => <option key={year}>Year {year}</option>)}</select></label><label className="text-xs font-bold text-blue-950">Email or phone<input required name="contact" placeholder="How can we reach you?" className="outline-ring mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm font-normal text-slate-700 placeholder:text-slate-400 focus:border-blue-900 focus:bg-white" /></label></div><div className="mt-7 grid gap-5 border-t border-slate-100 pt-7 sm:grid-cols-2"><label className="text-xs font-bold text-blue-950">Current club<select required name="current_club" defaultValue="" className="outline-ring mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-xs text-slate-700 focus:border-blue-900"><option value="" disabled>Choose current club</option>{availableClubs.map((club) => <option key={club.id} value={club.id}>{club.name} · {club.audience}</option>)}</select></label><label className="text-xs font-bold text-blue-950">Requested club<select required name="requested_club" defaultValue="" className="outline-ring mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-xs text-slate-700 focus:border-blue-900"><option value="" disabled>Choose requested club</option>{availableClubs.map((club) => <option key={club.id} value={club.id}>{club.name} · {club.audience}</option>)}</select></label></div><label className="mt-6 block text-xs font-bold text-blue-950">Why would you like to change?<textarea required name="reason" rows={4} placeholder="A short explanation helps us review your request." className="outline-ring mt-2 w-full resize-none rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm font-normal text-slate-700 placeholder:text-slate-400 focus:border-blue-900 focus:bg-white" /></label><button disabled={busy} className="mt-7 flex w-full items-center justify-center rounded-xl bg-blue-900 py-4 text-sm font-bold text-white transition hover:bg-blue-950 disabled:opacity-50">{busy ? "Sending request..." : "Send change request"}<ArrowRight size={16} className="ml-2" /></button></form></div></main>;
}
